## Simple `localStorage`-Based Caching System for API Responses

### Key Features:
- Cache API responses per city.
- Set a Time-To-Live (TTL) for cached data (e.g., 1 hour) to keep data fresh.
- Retrieve cached data if valid, otherwise fetch from API.
- Store cached data as JSON strings in `localStorage`.
- Keep the implementation dependency-free and minimal.

---

### Example Implementation

```javascript
const CACHE_PREFIX = 'weather_cache_';
const CACHE_TTL = 60 * 60 * 1000; // 1 hour in milliseconds

/**
 * Get cached weather data for a city if it exists and is fresh.
 * @param {string} city - City name
 * @returns {object|null} Cached data or null if not found/expired
 */
function getCachedWeather(city) {
  const cacheKey = CACHE_PREFIX + city.toLowerCase();
  const cachedString = localStorage.getItem(cacheKey);
  if (!cachedString) return null;

  try {
    const cached = JSON.parse(cachedString);
    if (cached.timestamp && (Date.now() - cached.timestamp) < CACHE_TTL) {
      return cached.data;
    } else {
      // Cache expired
      localStorage.removeItem(cacheKey);
      return null;
    }
  } catch (e) {
    // Corrupted cache data
    localStorage.removeItem(cacheKey);
    return null;
  }
}

/**
 * Save weather data to cache with current timestamp.
 * @param {string} city - City name
 * @param {object} data - API response data to cache
 */
function setCachedWeather(city, data) {
  const cacheKey = CACHE_PREFIX + city.toLowerCase();
  const cacheEntry = {
    data,
    timestamp: Date.now()
  };
  localStorage.setItem(cacheKey, JSON.stringify(cacheEntry));
}

/**
 * Fetch weather data with caching.
 * @param {string} city - City name
 * @param {string} apiKey - Your OpenWeather API key
 * @returns {Promise<object|null>} Weather data or null on error
 */
async function fetchWeather(city, apiKey) {
  // Try to get cached data first
  const cachedData = getCachedWeather(city);
  if (cachedData) {
    console.log(`Serving cached data for ${city}`);
    return cachedData;
  }

  // If no valid cache, fetch from API
  const url = `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${apiKey}&units=metric`;

  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`API error: ${response.status} ${response.statusText}`);
    }
    const data = await response.json();

    // Cache the fresh data
    setCachedWeather(city, data);

    return data;
  } catch (error) {
    console.error('Fetch weather error:', error);
    return null;
  }
}
```

